using Godot;
using GArray=Godot.Collections.Array;
public partial class ActorInspectorOperations
{
    private void AssignReference(Control owner,Resource actor,Resource? parent,Resource definition,Resource property,Variant value){if(parent==null)_batch.edit(Ui<RefCounted>(owner,"property_batch"),actor,property.Get("id").AsStringName(),value);else _timeline.edit_object_property(Ui<RefCounted>(owner,"model"),actor,parent,definition,property.Get("id").AsStringName(),value);owner.Call("_rebuild_selected");}
    public void object_menu_action(Control owner,int id,Resource actor,Resource? parent,Resource ownerDefinition,Resource property,Resource definition,GArray choices)
    {
        if(id is 1 or 7){owner.Call("_pick_actor_object_resource",actor,parent!=null?Variant.From(parent):default,ownerDefinition,property,definition,id==7);return;}var value=parent==null?_data.get_value(actor,property.Get("id").AsStringName(),default):_data.object_get_value(parent,property.Get("id").AsStringName(),default);var reference=value.VariantType==Variant.Type.Object?value.AsGodotObject() as Resource:null;var data=resolve_object(reference);if(id==6){if(data!=null)Clipboard()?.Call("quick_save",data,actor.Get("display_name").AsString()+" "+definition.Get("display_name").AsString());return;}if(id>=100){int index=id-100;if(index>=0&&index<choices.Count)AssignReference(owner,actor,parent,ownerDefinition,property,_data.from_object(_definitions.create_object(choices[index].As<Resource>())));return;}switch(id){case 2:if(data!=null)AssignReference(owner,actor,parent,ownerDefinition,property,_data.from_object(_data.copy_object(data)));break;case 3:if(data!=null){if(parent==null)owner.Call("_save_object_resource",actor,ownerDefinition,property,definition,data);else owner.Call("_save_nested_object_resource",actor,parent,ownerDefinition,property,definition,data);}break;case 4:AssignReference(owner,actor,parent,ownerDefinition,property,default);break;}
    }
    public void actor_object_resource_chosen(Control owner,Resource actor,Resource? parent,Resource definition,Resource property,string path){if(path==GD.Load<GDScript>("res://scripts/actors/core/actor_project_file_picker.gd").GetScriptConstantMap()["EMPTY_RESOURCE"].AsString()){AssignReference(owner,actor,parent,definition,property,default);return;}if(path.Length==0)return;if(parent==null)assign_object_resource_path(owner,actor,definition,property,path);else assign_nested_object_resource_path(owner,path,actor,parent,definition,property);}
}
